			function onBodyLoad(/* cpr.events.CEvent */ e){

			     /*공통 서비스 호출 (공통코드, 현재일자 등)*/
			    util.Submit.send(app, "subOnLoad", function(pbSuccess) {

			        var voInitValue = app.getHostProperty("initValue");

			        if(voInitValue){
			            sType          = voInitValue.type;
			            var selectData = voInitValue.selectData;

			            util.DataMap.clear(app, "dmCreativeInfo");

			            var voDsMap = app.lookup("dmCreativeInfo");
			            voDsMap.setValue("TYPE", sType);

			            // 부모창에서 전달받은 ROW DATA 셋팅
			            if(sType == "CREATE") {
			                voDsMap.setValue("CASE_MNG_NO"   , voInitValue.caseMngNo);
			                voDsMap.setValue("CASE_MNG_ODRNO", voInitValue.caseMngOrdno);
			                voDsMap.setValue("USE_YN"        , "Y");
			    
			            } else if(sType == "MODIFY") {
			                if(selectData.length > 0) {
			                    var data    = selectData[0];
			    
			                    voDsMap.setValue("CASE_MNG_NO"          , data.CASE_MNG_NO);
			                    voDsMap.setValue("CASE_MNG_ODRNO"       , data.CASE_MNG_ODRNO);
			                    voDsMap.setValue("INDEX_SN"             , data.INDEX_SN);                
			                    voDsMap.setValue("ACTVT_YR"             , data.YR);
			                    voDsMap.setValue("EXPRN_ACTVT_KND_SE_CD", data.RELM);
			                    voDsMap.setValue("ACTVT_HR"             , data.HR);
			                    voDsMap.setValue("PRTCLR_MATTER_CN"     , data.SPCABL_MATTER);
			                    voDsMap.setValue("ATFINO"               , data.ATFINO);
			                    voDsMap.setValue("USE_YN"               , data.USE_YN);
			                }
			            }

			            //첨부파일 정보 조회
			            app.lookup("cmnMultifileUpload").getFiles();

			            util.Control.redraw(app, "grp1");

			            // TYPE(등록 or 수정)에 따른 버튼 visible 처리
			            app.lookup("btnReg")  .visible = false;
			            app.lookup("btnMdfcn").visible = false;        

			            if(sType == "CREATE") {
			                app.lookup("btnReg")  .visible = true;
			    
			            } else if(sType == "MODIFY") {
			                app.lookup("btnMdfcn").visible = true;
			    
			            }
			        }
			    });
			}

